import java.io.*;
import java.net.http.*;
import java.net.URI;
import java.util.*;
import java.util.concurrent.*;
import com.sun.net.httpserver.*;
import org.json.*;

public class WebhookProcessor {
    private static final String CALLBACK_BASE = System.getenv("CALLBACK_BASE_URL");
    private static final ExecutorService pool = Executors.newFixedThreadPool(4);
    private static final HttpClient client = HttpClient.newBuilder()
            .followRedirects(HttpClient.Redirect.ALWAYS)
            .connectTimeout(java.time.Duration.ofSeconds(10))
            .build();

    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new java.net.InetSocketAddress(8080), 0);
        server.createContext("/webhook/subscribe", WebhookProcessor::handleSubscribe);
        server.createContext("/webhook/test", WebhookProcessor::handleTest);
        server.createContext("/internal/health", WebhookProcessor::handleHealth);
        server.setExecutor(pool);
        server.start();
    }

    static void handleHealth(HttpExchange ex) throws IOException {
        ex.sendResponseHeaders(200, 2);
        ex.getResponseBody().write("OK".getBytes());
        ex.getResponseBody().close();
    }

    static void handleSubscribe(HttpExchange ex) throws IOException {
        if (!"POST".equals(ex.getRequestMethod())) {
            ex.sendResponseHeaders(405, 0); ex.getResponseBody().close(); return;
        }
        String body = new String(ex.getRequestBody().readAllBytes());
        JSONObject json = new JSONObject(body);
        String callbackUrl = json.getString("callback_url");
        String secret = json.optString("secret", "");

        // Validate URL format
        if (!callbackUrl.startsWith("http://") && !callbackUrl.startsWith("https://")) {
            sendJson(ex, 400, "{\"error\":\"Invalid URL scheme\"}");
            return;
        }

        // Block obvious internal ranges
        try {
            URI uri = URI.create(callbackUrl);
            String host = uri.getHost();
            if (host == null || host.equals("localhost") || host.equals("127.0.0.1")) {
                sendJson(ex, 400, "{\"error\":\"Internal addresses not allowed\"}");
                return;
            }
        } catch (Exception e) {
            sendJson(ex, 400, "{\"error\":\"Malformed URL\"}");
            return;
        }

        // Verify callback URL is reachable with a challenge
        String challenge = UUID.randomUUID().toString();
        pool.submit(() -> verifyAndRegister(callbackUrl, secret, challenge));
        sendJson(ex, 202, "{\"status\":\"verification_pending\",\"challenge\":\"" + challenge + "\"}");
    }

    static void verifyAndRegister(String callbackUrl, String secret, String challenge) {
        try {
            // SSRF: fetches attacker-controlled URL, follows redirects to internal services
            String verifyUrl = callbackUrl + "?challenge=" + challenge;
            HttpRequest req = HttpRequest.newBuilder()
                    .uri(URI.create(verifyUrl))
                    .header("X-Webhook-Secret", secret)
                    .GET()
                    .build();
            HttpResponse<String> resp = client.send(req, HttpResponse.BodyHandlers.ofString());

            if (resp.statusCode() == 200 && resp.body().contains(challenge)) {
                // Store webhook registration (simplified)
                System.out.println("Registered webhook: " + callbackUrl);
            }
        } catch (Exception e) {
            System.err.println("Verification failed: " + e.getMessage());
        }
    }

    static void handleTest(HttpExchange ex) throws IOException {
        if (!"POST".equals(ex.getRequestMethod())) {
            ex.sendResponseHeaders(405, 0); ex.getResponseBody().close(); return;
        }
        String body = new String(ex.getRequestBody().readAllBytes());
        JSONObject json = new JSONObject(body);
        String targetUrl = json.getString("url");
        String payload = json.optString("payload", "{\"test\":true}");

        // Send test webhook payload to the registered URL
        try {
            HttpRequest req = HttpRequest.newBuilder()
                    .uri(URI.create(targetUrl))
                    .header("Content-Type", "application/json")
                    .POST(HttpRequest.BodyPublishers.ofString(payload))
                    .build();
            HttpResponse<String> resp = client.send(req, HttpResponse.BodyHandlers.ofString());
            sendJson(ex, 200, "{\"status\":" + resp.statusCode() + ",\"body\":\"" + 
                    resp.body().replace("\"", "\\\"").substring(0, Math.min(resp.body().length(), 500)) + "\"}");
        } catch (Exception e) {
            sendJson(ex, 502, "{\"error\":\"" + e.getMessage() + "\"}");
        }
    }

    static void sendJson(HttpExchange ex, int code, String json) throws IOException {
        byte[] b = json.getBytes();
        ex.getResponseHeaders().set("Content-Type", "application/json");
        ex.sendResponseHeaders(code, b.length);
        ex.getResponseBody().write(b);
        ex.getResponseBody().close();
    }
}
